"""Generate packages/contracts/outreach.schema.json and outreach.ts from the models of the outreach API (job DR A3). Same scheme as the other contracts (`make contracts`; a test fails if a file is stale)."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.outreach import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/outreach/models.py. Do not edit.\n"
    "// Batch plans, standing rules per lead source, caps, outcomes of calls, hot-lead hand-offs and reports. Approved once by the Owner with a second factor.\n"
)
RESPONSES: list[type[BaseModel]] = [m.PolicyOut, m.BatchAnswer, m.ItemsOut, m.RuleOut, m.ResultOut, m.HandoffOut, m.ReportOut, m.SourceCostOut]
REQUESTS: list[type[BaseModel]] = [m.PolicyIn, m.BatchIn, m.ExcludeIn, m.ApproveIn, m.CapsIn, m.RuleIn, m.ResultIn, m.SourceCostsIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "outreach.schema.json",
        "title": "Speed to lead and approve once (job DR A3)",
        "description": "Generated from services/ai-api/app/outreach/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
